import { Component } from '@angular/core';
import { Subject, of, timer, throwError } from 'rxjs';
import { catchError, debounceTime, delay, distinctUntilChanged, switchMap, tap, takeUntil } from 'rxjs/operators';

interface Result {
  id: number;
  name: string;
  email: string;
}

const FAKE_DATA: Result[] = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
  { id: 3, name: 'Charlie Kim', email: 'charlie@example.com' },
  { id: 4, name: 'Diana Lopez', email: 'diana@example.com' },
  { id: 5, name: 'Ethan Brown', email: 'ethan@example.com' },
  { id: 6, name: 'Fiona Patel', email: 'fiona@example.com' }
];

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  // Raw input value (for displaying in the header / status text)
  query = '';

  // Results, loading and error state used in the template
  results: Result[] = [];
  isLoading = false;
  error: string | null = null;

  // Stream of search terms coming from the input
  private searchTerm$ = new Subject();

  // Used to clean up the subscription
  private destroy$ = new Subject();

  constructor() {
    this.setupSearchStream();
  }

  // Called from the template on every input event
  onQueryChange(value: string): void {
    this.query = value;
    this.searchTerm$.next(value);
  }

  ngOnDestroy(): void {
    this.destroy$.next(null);
    this.destroy$.complete();
  }

  private setupSearchStream(): void {
    this.searchTerm$
      .pipe(
        debounceTime(500),
        distinctUntilChanged(),
        tap((term: unknown) => {
          const value = String(term ?? '').trim();

          // Empty query: clear results & states immediately
          if (!value) {
            this.results = [];
            this.isLoading = false;
            this.error = null;
          } else {
            this.isLoading = true;
            this.error = null;
          }
        }),
        switchMap((term: unknown) => {
          const value = String(term ?? '');
          const trimmed = value.trim();

          if (!trimmed) {
            // Skip API when query is empty
            return of([]);
          }

          return this.fakeApiSearch(trimmed).pipe(
            catchError((err: unknown) => {
              const message = err instanceof Error ? err.message : 'Something went wrong.';
              this.error = message;
              this.isLoading = false;
              return of([]);
            })
          );
        }),
        takeUntil(this.destroy$)
      )
      .subscribe((results: Result[]) => {
        this.results = results;
        this.isLoading = false;
      });
  }

  // Fake API: filters the in-memory array and responds after a delay.
  private fakeApiSearch(term: string) {
    const trimmed = term.trim().toLowerCase();
    const delayMs = 600;

    if (!trimmed) {
      return of([]).pipe(delay(delayMs));
    }

    const filtered = FAKE_DATA.filter((item) => {
      const name = item.name.toLowerCase();
      const email = item.email.toLowerCase();
      return name.includes(trimmed) || email.includes(trimmed);
    });

    // Deliberately fail for the query "error" so students can see error handling.
    if (trimmed === 'error') {
      return timer(delayMs).pipe(
        switchMap(() => throwError(() => new Error('Fake API error')))
      );
    }

    return of(filtered).pipe(delay(delayMs));
  }
}

